<?php
namespace App\Http\Controllers\Frontend;
use App\Http\Controllers\Controller;use App\Models\{GiftCard,WalletTransaction};use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class WalletController extends Controller{public function index(){return view('frontend.user.wallet',['transactions'=>auth()->user()->walletTransactions()->latest()->paginate(20)]);}public function redeem(Request $r){$d=$r->validate(['code'=>'required|string|max:40']);$user=auth()->user();$code=strtoupper(trim($d['code']));try{DB::transaction(function()use($user,$code){$card=GiftCard::where('code',$code)->lockForUpdate()->first();if(!$card||$card->status!=='active'||$card->current_balance<=0||($card->expires_at&&$card->expires_at->isPast()))throw new \RuntimeException('invalid_card');$amount=(float)$card->current_balance;$user=\App\Models\User::whereKey($user->id)->lockForUpdate()->firstOrFail();$new=(float)$user->store_credit+$amount;$user->update(['store_credit'=>$new]);WalletTransaction::create(['user_id'=>$user->id,'type'=>'gift_card','amount'=>$amount,'balance_after'=>$new,'note'=>'Redeemed gift card '.$card->code]);$card->transactions()->create(['user_id'=>$user->id,'type'=>'redeem','amount'=>-$amount,'balance_after'=>0,'note'=>'Transferred to customer store credit']);$card->update(['current_balance'=>0,'status'=>'redeemed']);});}catch(\RuntimeException $e){if($e->getMessage()==='invalid_card')return back()->with('error','Gift card is invalid, empty or expired.');throw $e;}return back()->with('success','Gift card redeemed into store credit.');}}
